# 큐보 3권 조향자동차(교재 22~30쪽, 1~45번+완성) — 조립 프로그램(asmlib)으로 만든다. (교재 PDF 쪽 번호 = 교재 쪽 번호. 조향자동차 = 3권 2차시, 1차시는 배틀바이크 — 2026-10-26 사용자 정정)
# 순서대로 만든다: 1단계 → 확인 → 2단계 → 확인 …  (뒤에서부터 만들거나 중간부터 시작하지 않는다)
# 각 단계: 교재 그림을 왼쪽→오른쪽, 위→아래로 읽고(부품·초록 원·화살표), get_step_context 로 직전 상태(쓴 부품·남은 부품·빈 구멍)를 본 뒤 적는다.
# 교재 LIST(부품 목록, 30개 종류):
#   2단블록 6
#   3단블록 14
#   15프레임 2
#   17프레임 5
#   115프레임 2
#   25프레임 3
#   27프레임 2
#   35프레임 5
#   37프레임 1
#   315프레임 2
#   515프레임 2
#   713프레임 1
#   135도 프레임 2
#   리벳 30
#   부시 12
#   T축 1
#   축 4
#   큰기어 2
#   DC모터 2
#   메인보드 1
#   리모컨 1
#   중간바퀴 4
#   LED센서 2
#   3P 케이블 2
#   너트 7
#   8볼트 5
#   12볼트 3
#   서보모터 1
#   서보고정볼트 1
#   서보혼 1
import json, sys
import numpy as np
from asmlib import *

A = Asm("cubo-3-steercar", "조향자동차", "교재 22~30쪽 · 조향자동차 (1~45단계)", camera={"target": [60, 20, 0], "radius": 380, "theta": 0.9, "phi": 1.0},
        listNote="만드는 중 — 단계가 끝나기 전까지 LIST 개수는 안 맞는 것이 정상", guideMode="mates")   # 연결점은 부품에 붙어 있고 결합할 자리일 때만 보인다(맞물림 방식, 사용자 지시 2026-10-04)
RELOCK = "--relock" in sys.argv   # 잠금 기록을 새로 만들 때(수정 지시는 이번 빌드에서 무시한다)
if not RELOCK: A.load_fixes("steercar_fixes.json")   # 관리자 수정 지시(앞 단계 수정 → 뒤 단계가 따라온다). 파일이 없으면 아무 일도 안 한다
A.load_links("steercar_links.json", relock=RELOCK)   # 좌표로 쓴 결합·절대 좌표로 놓은 판을 이름으로 잠가 두는 기록
UP = (0, 1, 0)

# ── 1 ── (교재 1: 첫 부품은 pt/place 로 직접 놓고, 나머지는 이름으로 결합한다)
# 예)  s1 = A.step("[교재 1] ...")
#      base = s1.place("315프레임", orient("315프레임", {"홀면 +y": "위"}), (75, 2.5, 0))
#      blk  = s1.attach("3단블록", orient("3단블록", {"돌기면 +z": "아래", "홀면 +y": "+Z"}), {"돌기면 +z 1": ("315프레임 1번", "홀면 +y 열14·줄1"), "돌기면 +z 3": ("315프레임 1번", "홀면 +y 열15·줄1")}, hover=45)
# 구멍·돌기는 이름(면 +축, 열·줄)으로 말한다(안내서 3-1절). 번호를 모르면 get_part_faces / get_step_context 로 본다.

# ── 단계 번호 등록(작업 흐름 단계 1): 교재 22~30쪽 훑어 정리 — 모든 단계를 noPart 뼈대로 둔다. 번호 작업 때 SKEL[n-1].kw.pop("noPart", None) 하고 note 를 채운다 ──
# 쪽 표: 22쪽 완성품 사진·LIST·1~2 / 23쪽 3~8 / 24쪽 9~14 / 25쪽 15~20 / 26쪽 21~26 / 27쪽 27~32 / 28쪽 33~38 / 29쪽 39~44 / 30쪽 45+완성. (31쪽 작동 방법·32쪽 프로그램은 이 조립도 밖; 1번 = 메인보드 OUT3 에 서보모터 연결해 영점 조절 후 분리)
_PAGE = {**{n: 22 for n in (1, 2)}, **{n: 23 for n in range(3, 9)}, **{n: 24 for n in range(9, 15)}, **{n: 25 for n in range(15, 21)},
         **{n: 26 for n in range(21, 27)}, **{n: 27 for n in range(27, 33)}, **{n: 28 for n in range(33, 39)}, **{n: 29 for n in range(39, 45)}, **{n: 30 for n in (45,)}}
SKEL = [A.step("[교재 %d] (작성 전) 교재 %d쪽 — 번호만 등록한 뼈대. 번호 작업 때 채운다." % (_n, _PAGE[_n]), noPart=True) for _n in range(1, 46)]
for _k in range(1, 46): A.steps[_k - 1].cam = (-0.79, 0.95, False, None, None, None); A.steps[_k - 1].camSrc = "guess"   # 카메라: 번호 작업 전까지는 같은 값의 짐작(guess)

# ── 1 ── 교재 22쪽 1 (읽은 것 2026-10-26) 서보모터를 메인보드 OUT3 에 연결해 영점 조절하는 안내 그림 — 새로 결합하는 부품은 없고 서보모터만 나온다
#   책 1번 그림에는 초록 링·화살표가 없다(메인보드 OUTPUT 3 단자에 서보모터 케이블이 꽂힌 그림). 케이블·메인보드는 3D 모델 연결이 없어 그리지 않는다(볼링머신·투석기 35번과 같은 방식, 사용자 지시 2026-10-12). 메인보드는 43번에서 올린다.
#   서보모터는 책 그림처럼 출력축(황동 원통)이 위로 오게 세워 원점에 둔다(모델 로컬 y 가 위, 출력축 p1 이 +y).
s1 = SKEL[0]; s1.kw.pop("noPart", None)
s1.note = "[교재 1] 서보모터를 메인보드 OUTPUT 3 단자에 연결하고 전원을 켜서 영점을 맞춰요. 영점 조절이 끝나면 메인보드와 분리한 다음 2번부터 조립해요. (케이블·메인보드는 3D 로 그리지 않아요.)NL▣ 사용 부품: 서보모터 1".replace("NL", chr(10))
R_SV = np.array([[0, 0, -1], [0, 1, 0], [1, 0, 0]], float)   # 서보모터 Ry(−90°): 출력축 +y 위, 케이블 쪽(모델 +z)이 −X, 큰 면(모델 +x)이 +Z — 2번에서 돌기 p2·p3·p4(x −9·+1·+11)가 515프레임 줄 3 의 칸 6·7·8 에 들어가는 자세
SV1 = s1.place("서보모터", R_SV, (0, 25.25, 0))   # 돌기 뿌리(모델 y −20.25)가 판 윗면 y 5 에 오는 높이: 25.25
SV1.extra["loose"] = True   # 아직 아무것에도 끼우지 않은 첫 부품(2번에서 판에 얹는다) — 허공 검사 제외
A.steps[0].cam = (0.87, 0.5, False, None, None, None); A.steps[0].camSrc = "eye"   # axes_fit.py 결과: 서보 날개 구멍 6점(01_P.json) 오차 0.54px, theta 0.87 phi 0.50(roll 5.8°) — 구멍 3D 간격은 추정(모델에 날개 구멍 없음)

# ── 2 ── 교재 22쪽 2 (읽은 것 2026-10-26, 격자 02_P(515프레임 15칸×5줄, holefit DoG 42점 평균 1.28px), axes_fit 오차 1.27px theta −0.54 phi 0.69)
#   카메라가 보는 면(책): 구멍 큰 검은 515프레임이 홀면 위로 놓였고 칸1 이 왼쪽(가까운 끝)·칸15 가 오른쪽(먼 끝)으로 오른쪽 위로 뻗는 대각선 샷. 줄1 = 먼 줄, 줄5 = 가까운 줄. 서보모터는 판 위에 떠 있고 흰 케이블이 왼쪽으로 나가며 큰 'Cubo' 면이 가까운 쪽(+Z)을 본다.
#   초록 링(꼬리 = 서보 돌기, 화살촉 = 판 구멍): 줄 3 의 칸 6·7·8 — 초록 둘(칸 6·8) + 노랑 하나(칸 7: 아래에서 서보고정볼트가 올라와 서보 가운데 돌기 속 나사 구멍에 조인다).
#   서보 자세(책): 케이블 쪽이 왼쪽(−X) = 서보 돌기 p2(케이블 쪽 긴 돌기, x −9)가 칸 6, p3(x +1)이 칸 7, p4(x +11)가 칸 8. 출력축은 위(+y).
import os as _os2
_HOLD2 = bool(_os2.environ.get("STEERCAR_HOLD2"))   # 1번 내용을 고친 뒤 증거를 다시 남길 때만: 2번을 잠시 빼서 1번이 마지막 번호가 되게 한다(증거 재작성 후 반드시 끄고 다시 빌드)
if not _HOLD2:
    s2 = SKEL[1]; s2.kw.pop("noPart", None)
    s2.note = "[교재 2] 515프레임(구멍 큰 검은 판) 위에 서보모터를 얹어요. 서보모터 아래 돌기 셋이 판의 가운데 줄 칸 6·7·8 구멍에 들어가고, 판 아래에서 서보고정볼트를 칸 7 구멍으로 끼워 서보모터에 조여요. 케이블이 나온 쪽이 왼쪽이에요." + chr(10) + "▣ 사용 부품: 515프레임 1, 서보고정볼트 1"
    PL2 = s2.place("515프레임", np.eye(3), (11.0, 2.5, 0.0))   # 판 윗면 y 5, 칸 k 의 구멍 x = 11 + (k−8)×10 → 칸 6·7·8 = −9·+1·+11 (서보 돌기 p2·p3·p4)
    _mk2 = {id(SV1): [[-9.0, 5.0, 0.0], [11.0, 5.0, 0.0]]}   # 초록 링 둘 = 판 윗면 구멍 입구 칸 6·8(줄 3). 칸 7 노랑 링은 서보고정볼트가 위로 올라오는 구멍(볼트 안내점)
    s2.move_made(Group("서보모터", [SV1]), np.eye(3), pivot=None, shift=(0.0, 0.0, 0.0), dir=[0, 1, 0], hover=45, group="mm2servo", marks=_mk2)   # 책에서 서보가 판 위로 내려온다 — 제자리는 돌기 셋이 칸 6·7·8 구멍에 들어간 자리
    R_BOLT_UP = np.diag([1.0, -1.0, -1.0])   # 볼트·너트: 돌기가 +Y 를 본다(머리·몸이 판 아래/위)
    BT2 = s2.attach("서보고정볼트", R_BOLT_UP, {"p1": (PL2, "h7_3")}, hover=45, dir=[0, -1, 0])   # 머리가 판 아래, 몸통이 위로 칸 7 줄 3 을 지나 서보 가운데 돌기 속으로
    A.meta["lift"] = {"2": 50.0}   # 서보고정볼트가 판 아래로 내려오는 번호 — 화면을 올림(볼트 머리 제자리 y −1.3, 띄움 −46)
    for _i in range(3, 46): A.meta["lift"][str(_i)] = 5.0   # 볼트 머리가 판 아래 y −1.3 까지 내려가 있으므로 이후 번호도 5 올린다(바닥이 y 0 에 닿게) — 뒤 번호에서 몸 방향이 바뀌면 다시 본다
    A.steps[1].cam = (-0.54, 0.69, False, None, None, None); A.steps[1].camSrc = "eye"   # axes_fit.py 결과(02_P.json 75점 중 42점, 오차 1.27px, roll 2.0°)

    # ── 3 ── 교재 23쪽 3 (읽은 것 2026-10-31 — 2번 몸(515프레임+서보모터) 아래에 115프레임을 리벳 2개로 잇고 8볼트·너트로 조인다)
    #   카메라가 보는 면(책): 판 15열 쪽 끝(가까운 끝)이 화면 아래, 칸1(서보 케이블이 나가는 쪽)이 위 오른쪽 먼 끝 — 2번과 반대쪽(+X 끝·−Z 쪽)에서 본다(제 판단: 케이블이 먼 쪽으로 나가고 4구멍 끝면·−Z 쪽 평평한 옆면이 보이는 것으로 읽음). 줄5 = 화면 왼쪽(+Z), 줄1 = 오른쪽(−Z).
    #   링: 판 15열 줄4(초록)·줄3(노랑 = 8볼트)·줄2(초록) — 링 픽셀 (425.0,429.9)·(470.0,445.0)·(515.8,462.2) 가 03_P.json 격자 칸 15·4/15·3/15·2 에서 0.5px 안(infer_grid 앵커 평균 0.53·최대 0.73px, 선명한 구멍 20개 평균 0.86·최대 2.64px, 가설 유일성 13.94). 링 셋은 연속 세 구멍(10mm).
    #   115프레임(흰 프레임, 구멍 15): 구멍 7·9 에 리벳(초록 링 둘의 바로 아래), 구멍 8 이 노랑 링(볼트·너트) — 가운데 구멍 8 이 판 줄3 바로 아래, 길이는 판 줄 방향(Z). 판 03_P 카메라로 프레임 구멍 15개를 순방향 투영하면(판 아래 y −30) 읽은 구멍 12개와 평균 3.39px(03_U.json).
    #   책 화살표는 판 링에서 리벳 쪽으로 아래로 향한다 = 판(몸)이 프레임 위로 내려온다(2번의 서보처럼 몸을 위에 띄워 move_made). 리벳은 항상 결합 전(사용자 규칙): 프레임 위에 hover 25 로 떠 있고 몸은 hover 55 로 더 위에서 내려온다(책은 리벳이 프레임에 꽂힌 모양이지만 분리해 화살표를 그린다).
    s3 = SKEL[2]; s3.kw.pop("noPart", None)
    s3.note = "[교재 3] 515프레임 판 아래에 115프레임을 이어요. 리벳 2개를 115프레임 구멍 7·9 에 끼우고 그 위로 판의 끝 열(15열) 줄 4·2 구멍을 내려요. 8볼트를 판 줄 3 구멍으로 넣어 115프레임 가운데 구멍을 지나 아래에서 너트로 조여요." + chr(10) + "▣ 사용 부품: 115프레임 1, 리벳 2, 8볼트 1, 너트 1"
    R_FR3 = np.array([[0.0, 0.0, -1.0], [0.0, -1.0, 0.0], [-1.0, 0.0, 0.0]])   # 115프레임: 길이(로컬 x) → 세계 −Z(구멍 1 이 +Z 끝 = 화면 왼쪽), 구멍면이 위
    FR3 = s3.place("115프레임", R_FR3, (81.0, -2.5, 0.0))   # 판 15열(구멍 x = 11 + (15−8)×10 = 81) 바로 아래 가운데(구멍 8 이 줄3), 윗면이 판 밑면 y 0 에 닿는다(리벳 결합 프레임 틈 0)
    FR3.extra["loose"] = True   # 이 번호에서 처음 놓는 부품(리벳이 위에서 꽂힌다) — 허공 검사 제외
    RV3 = [s3.attach("리벳", np.eye(3), {"p1": (FR3, "h%d_1" % _k)}, rivet=True, hover=25, dir=[0, 1, 0]) for _k in (7, 9)]   # 리벳 아래 끝 p1 이 프레임 구멍 7(줄4 쪽)·9(줄2 쪽)에
    _mk3 = {id(PL2): [[81.0, 0.0, 10.0], [81.0, 0.0, -10.0]]}   # 초록 링 둘 = 판 15열 줄4·줄2 구멍 입구(판 밑면 y 0), 화살촉이 리벳 윗 끝에 닿는다
    s3.move_made(Group("몸(1~2번)", [PL2, SV1, BT2]), np.eye(3), pivot=None, shift=(0.0, 0.0, 0.0), dir=[0, 1, 0], hover=55, group="mm3body", marks=_mk3)   # 책에서 판(서보모터 얹은 몸)이 위에서 내려온다 — 제자리는 판이 프레임에 딱 붙은 자리
    BT3 = s3.attach("8볼트", np.eye(3), {"p1": (PL2, "h15_3")}, hover=100, dir=[0, 1, 0])   # 판 15열 줄3(노랑 링)에서 아래로 — 몸이 55 떠 있으므로 그보다 위
    NT3 = s3.attach("너트", np.eye(3), {"p1": (FR3, "h8_1")}, hover=40, dir=[0, -1, 0])   # 프레임 구멍 8 아래에서 올라와 볼트 끝을 받는다
    A.meta["lift"]["3"] = 55.0   # 너트가 프레임 아래로 내려와 바닥 아래로 가므로 화면을 올린다
    for _i in range(4, 46): A.meta["lift"][str(_i)] = 10.0   # 프레임 밑면 y −5·너트가 몸 아래에 붙어 있으므로 이후 번호는 10 올린다(바닥이 y 0 에 닿게) — 뒤 번호에서 몸 방향이 바뀌면 다시 본다
    A.steps[2].cam = (1.94, 0.93, False, None, None, None); A.steps[2].camSrc = "eye"   # infer_grid.py 결과(03_P.json: 선명한 구멍 20개 평균 0.86px + 링 앵커 3곳 0.53px, roll 0.3°)

